import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Installation","description":"","frontmatter":{"title":"Installation"},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),i={name:"guide/installation.md"};function o(s,e,l,d,c,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="telecharger" tabindex="-1">Télécharger <a class="header-anchor" href="#telecharger" aria-label="Permalink to &quot;Télécharger&quot;">​</a></h2><p>Les fichiers sont dans la <a href="https://github.com/ArboRithm/Daimon/releases/latest" target="_blank" rel="noreferrer">dernière release</a>.</p><table tabindex="0"><thead><tr><th>Plateforme</th><th>Configuration</th><th>Fichier</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon, macOS 12 ou plus récent</td><td><code>Daimon_&lt;version&gt;_aarch64.dmg</code></td></tr><tr><td>Windows</td><td>Windows 10 version 2004 ou plus récent, x64</td><td><code>Daimon_&lt;version&gt;_x64-setup.exe</code></td></tr><tr><td>Windows (préversion)</td><td>Windows 10 version 2004 ou plus récent, ARM64</td><td><code>Daimon_&lt;version&gt;_arm64-setup.exe</code></td></tr></tbody></table><p>La version macOS est signée et notarisée par Apple. Le support de Windows ARM64 est une préversion : il n&#39;a pas encore été testé sur une vraie machine ARM.</p><h2 id="installer" tabindex="-1">Installer <a class="header-anchor" href="#installer" aria-label="Permalink to &quot;Installer&quot;">​</a></h2><p><strong>Installez avant d&#39;enregistrer vos clients IA</strong> : ils sont enregistrés avec l&#39;emplacement de l&#39;application.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Ouvrez le DMG et glissez Daimon dans <strong>Applications</strong>.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Lancez l&#39;installateur. Il est signé Authenticode, l&#39;éditeur affiché est ArboRithm. Si SmartScreen affiche malgré tout un avertissement, cliquez sur <strong>Informations complémentaires</strong>, puis sur <strong>Exécuter quand même</strong>.</p><p>Une fois installé, le programme se trouve dans <code>%LOCALAPPDATA%\\Daimon\\Daimon.exe</code>.</p><h2 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h2><ol><li>Lancez Daimon. Il vit dans la barre de menus sous macOS (pas d&#39;icône dans le Dock) et dans la zone de notification sous Windows, près de l&#39;horloge, éventuellement dans le menu de débordement.</li><li>Cliquez sur son icône pour ouvrir le <strong>panneau</strong>.</li><li>Choisissez <strong>Relancer l&#39;installation…</strong> : le parcours vous guide dans les autorisations (sous macOS) et vos clients IA.</li><li><strong>Redémarrez votre client IA</strong>, puis demandez-lui de regarder votre écran.</li></ol><p>Suite : <a href="./autorisations.html">Autorisations</a>.</p>',15)])])}const p=t(i,[["render",o]]);export{h as __pageData,p as default};
